{"command":"cat > /tmp/m.py <<'PY'
import numpy as np,base64,json,subprocess
sr=22050
# wave samples loops 0.25s
for inst,kind in [(1,'lead'),(2,'bass'),(3,'arp'),(4,'kick'),(5,'snare')]:
 n=4096;t=np.arange(n)/sr
 if kind=='lead': x=.7*np.sign(np.sin(2*np.pi*220*t))*.7+.3*np.sin(2*np.pi*440*t)
 elif kind=='bass': x=np.sin(2*np.pi*55*t)+.35*np.sin(2*np.pi*110*t)
 elif kind=='arp': x=np.sin(2*np.pi*330*t)+.5*np.sin(2*np.pi*660*t)
 elif kind=='kick': x=np.sin(2*np.pi*(80*t-60*t*t))*np.exp(-t*18)
 else:
  rng=np.random.default_rng(4); x=rng.normal(0,1,n)*np.exp(-t*20)
 x=np.clip(x*.55,-1,1); pcm=(x*32767).astype('<i2')
 arg={'instrument':inst,'pcm':base64.b64encode(pcm.tobytes()).decode(),'encoding':'int16','name':kind}
 subprocess.run(['ft2','call','sample_create_from_pcm',json.dumps(arg)],check=True,stdout=subprocess.DEVNULL)
 subprocess.run(['ft2','call','sample_set',json.dumps({'instrument':inst,'volume':48 if inst>3 else 52,'loop_start':0,'loop_length':n,'flags':1,'name':kind})],stdout=subprocess.DEVNULL)
 subprocess.run(['ft2','call','instrument_set',json.dumps({'instrument':inst,'name':kind.upper()})],stdout=subprocess.DEVNULL)
# batch cells
calls=[]; chords=[[45,48,52],[41,45,48],[43,47,50],[40,43,47]] # A minor etc
mel=[69,72,76,79,76,72,71,72,74,79,83,79,76,74,72,69]
for p in range(4):
 calls.append({'name':'pattern_set_length','arguments':{'pattern':p,'rows':64}})
 for r in range(64):
  beat=r%16; bar=r//16; chord=chords[(bar+p)%4]
  # lead melodic eighth notes, phrase varied
  if r%4==0:
   note=mel[((r//4)+p*3)%len(mel)]
   if p==3 and r>=48: note=[69,72,76,81][(r//4)%4]
   calls.append({'name':'pattern_set_cell','arguments':{'pattern':p,'row':r,'channel':0,'note':note,'instrument':1,'volume':48}})
  # arpeggio 16ths at every 4 rows
  if r%4==0:
   q=(r//4+p)%3
   calls.append({'name':'pattern_set_cell','arguments':{'pattern':p,'row':r,'channel':1,'note':chord[q]+12,'instrument':3,'volume':32}})
  if r%8==0:
   calls.append({'name':'pattern_set_cell','arguments':{'pattern':p,'row':r,'channel':2,'note':chord[0]-12,'instrument':2,'volume':52}})
  if r%16 in (0,8): calls.append({'name':'pattern_set_cell','arguments':{'pattern':p,'row':r,'channel':3,'note':48,'instrument':4,'volume':50}})
  if r%16 in (4,12): calls.append({'name':'pattern_set_cell','arguments':{'pattern':p,'row':r,'channel':4,'note':55,'instrument':5,'volume':38}})
  if r%16==0:
   calls.append({'name':'pattern_set_cell','arguments':{'pattern':p,'row':r,'channel':5,'note':chord[1],'instrument':3,'volume':28}})
 calls.append({'name':'order_set','arguments':{'position':p,'pattern':p}})
open('/tmp/calls.json','w').write(json.dumps(calls))
